package org.rabochaya.projects;
import java.io.*;import java.util.*;import java.util.regex.*;
/** Local SRTM1/3 one-degree, signed big-endian16 grid; no location or network. */
public final class HgtRaster implements Closeable {
 public static final long MAX_RAW=3601L*3601*2;private static final int MAGIC=0x524b4847,HEADER=32;
 private final RandomAccessFile file;private final int offset;public final int samples,west,south;public final String name;
 private final LinkedHashMap<Integer,short[]> rows=new LinkedHashMap<Integer,short[]>(16,.75f,true){protected boolean removeEldestEntry(Map.Entry<Integer,short[]> e){return size()>8;}};
 public HgtRaster(File source,String filename)throws IOException{this(source,filename,0,false);}
 public static HgtRaster owned(File file,long project)throws IOException{return new HgtRaster(file,null,project,true);}
 private HgtRaster(File source,String filename,long owner,boolean owned)throws IOException{file=new RandomAccessFile(source,"r");try{if(owned){if(owner<=0||file.readInt()!=MAGIC||file.readInt()!=1||file.readLong()!=owner)throw new IOException("DEM принадлежит другому проекту или повреждён");west=file.readInt();south=file.readInt();samples=file.readInt();if(file.readInt()!=0)throw new IOException("Неизвестный private DEM header");offset=HEADER;}else{Matcher m=Pattern.compile("([NS])(\\d{2})([EW])(\\d{3})\\.hgt",Pattern.CASE_INSENSITIVE).matcher(filename==null?"":filename);if(!m.matches())throw new IOException("Нужно имя HGT вида N55E037.hgt");south=Integer.parseInt(m.group(2))*(m.group(1).equalsIgnoreCase("S")?-1:1);west=Integer.parseInt(m.group(4))*(m.group(3).equalsIgnoreCase("W")?-1:1);long length=file.length();samples=length==1201L*1201*2?1201:length==MAX_RAW?3601:0;offset=0;}
  if(west< -180||west>179||south< -90||south>89||(samples!=1201&&samples!=3601)||file.length()!=offset+(long)samples*samples*2)throw new IOException("Нужен одноградусный SRTM HGT1201²/3601² int16; размер/границы не совпали");name=String.format(Locale.US,"%s%02d%s%03d.hgt",south<0?"S":"N",Math.abs(south),west<0?"W":"E",Math.abs(west));
 }catch(Exception e){file.close();if(e instanceof IOException)throw (IOException)e;throw new IOException("Не удалось открыть HGT",e);}}
 private short sample(int x,int y)throws IOException{short[] row=rows.get(y);if(row==null){byte[] bytes=new byte[samples*2];file.seek(offset+(long)y*samples*2);file.readFully(bytes);row=new short[samples];for(int i=0;i<samples;i++)row[i]=(short)((bytes[i*2]&255)<<8|(bytes[i*2+1]&255));rows.put(y,row);}return row[x];}
 /** Bilinear source metres, NaN outside coverage or if any weighted sample is void. */
 public synchronized double height(double lon,double lat)throws IOException{if(Double.isNaN(lon)||Double.isInfinite(lon)||Double.isNaN(lat)||Double.isInfinite(lat))return Double.NaN;if(west==179&&lon== -180)lon=180;else if(west== -180&&lon==180)lon= -180;double ex=32*Math.ulp(Math.max(1,Math.max(Math.abs(lon),Math.abs(west)))),ey=32*Math.ulp(Math.max(1,Math.max(Math.abs(lat),Math.abs(south+1))));if(lon<west-ex||lon>west+1+ex||lat<south-ey||lat>south+1+ey)return Double.NaN;lon=Math.max(west,Math.min(west+1,lon));lat=Math.max(south,Math.min(south+1,lat));double x=(lon-west)*(samples-1),y=(south+1-lat)*(samples-1);if(Math.abs(x-Math.rint(x))<=ex*(samples-1)+8*Math.ulp(Math.max(1,x)))x=Math.rint(x);if(Math.abs(y-Math.rint(y))<=ey*(samples-1)+8*Math.ulp(Math.max(1,y)))y=Math.rint(y);int left=Math.min(samples-1,(int)Math.floor(x)),top=Math.min(samples-1,(int)Math.floor(y));double dx=x-left,dy=y-top,result=0;for(int j=0;j<2;j++)for(int i=0;i<2;i++){double weight=(i==0?1-dx:dx)*(j==0?1-dy:dy);if(weight==0)continue;short value=sample(Math.min(samples-1,left+i),Math.min(samples-1,top+j));if(value==Short.MIN_VALUE)return Double.NaN;result+=value*weight;}return result;}
 /** Writes an owned temporary container; callers publish only after explicit guarded commit. */
 public static void prepare(File raw,String name,File temporary,long project)throws IOException{if(project<=0||raw.getCanonicalFile().equals(temporary.getCanonicalFile()))throw new IOException("Нужен собственный временный DEM");try(HgtRaster source=new HgtRaster(raw,name);FileOutputStream stream=new FileOutputStream(temporary);DataOutputStream out=new DataOutputStream(stream);InputStream in=new FileInputStream(raw)){out.writeInt(MAGIC);out.writeInt(1);out.writeLong(project);out.writeInt(source.west);out.writeInt(source.south);out.writeInt(source.samples);out.writeInt(0);byte[] buffer=new byte[65536];long copied=0;int n;while((n=in.read(buffer))!=-1){copied+=n;if(copied>MAX_RAW)throw new IOException("HGT превышает допустимый размер");out.write(buffer,0,n);}if(copied!=(long)source.samples*source.samples*2)throw new IOException("Исходный HGT изменился при копировании");out.flush();stream.getFD().sync();}}
 /** Explicit map navigation only; polar coverage outside Web Mercator is refused. */
 public double[] mapViewport(int width,int height)throws IOException{double limit=85.0511287798066,bottom=Math.max(south,-limit),top=Math.min(south+1,limit);if(!(top>bottom)||width<=0||height<=0)throw new IOException("Область DEM не отображается в этой проекции карты");return GeoRasterTransform.viewport(west,bottom,west+1,top,width,height);}
 public synchronized void close()throws IOException{rows.clear();file.close();}
}
